# Use simple greedy coloring with many attempts
import random
def greedy_coloring(adj, n, max_colors):
    for _ in range(10000):
        colors = [-1] * n
        order = list(range(n))
        random.shuffle(order)
        success = True
        for v in order:
            used = set()
            for u in adj[v]:
                if colors[u] != -1:
                    used.add(colors[u])
            for c in range(max_colors):
                if c not in used:
                    colors[v] = c
                    break
            if colors[v] == -1:
                success = False
                break
        if success:
            return True, colors
    return False, None

ok, cols = greedy_coloring(adj, n, 4)
print(f"4-colorable: {ok}")
if ok:
