def girth_of_generators(n, gens):
    adj = [set() for _ in range(n)]
    for i in range(n):
        for g in gens:
            j = (i + g) % n
            if j != i:
                adj[i].add(j)
                adj[j].add(i)
    # compute girth
    min_cycle = float('inf')
    for start in range(n):
        dist = [-1] * n
        parent = [-1] * n
        q = deque([(start, -1)])
        dist[start] = 0
        while q:
            v, p = q.popleft()
            for u in adj[v]:
                if dist[u] == -1:
                    dist[u] = dist[v] + 1
                    parent[u] = v
                    q.append((u, v))
                elif u != p and v < u:
                    cycle_len = dist[v] + dist[u] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

